package com.example.circuitbreakerdemo.client; import org.springframework.stereotype.*; import org.springframework.web.client.*; import com.example.circuitbreakerdemo.dto.*; @Component public class PaymentClient{ private final RestTemplate r; public PaymentClient(RestTemplate r){this.r=r;} public PaymentResponse pay(String id){ return r.getForObject("http://localhost:8080/payments/"+id, PaymentResponse.class);} }